//! Replays `tests/vectors/auth_vectors.json` (generated by
//! `tests/gen_auth_vectors.rs` from fixed seeds, task instruction) through
//! `c2_svc::auth::verify` -- the same function `POST /v1/auth/verify`'s
//! handler calls. Covers: positive, wrong address, wrong message, tampered
//! signature, and the all-hex message edge case (task instruction, exact
//! wording).

use c2_svc::auth::{AuthVerifyRequest, verify};
use serde::Deserialize;

#[derive(Deserialize)]
struct Vector {
    case: String,
    #[serde(rename = "seed_hex")]
    _seed_hex: String,
    address: String,
    public_key: String,
    message: String,
    signature: String,
    valid: bool,
}

fn load_vectors() -> Vec<Vector> {
    let json = include_str!("vectors/auth_vectors.json");
    serde_json::from_str(json).expect("tests/vectors/auth_vectors.json must be valid JSON")
}

#[test]
fn all_vectors_match_expected_validity() {
    let vectors = load_vectors();
    assert_eq!(vectors.len(), 5, "expected exactly the 5 task-instruction cases");

    let expected_cases = [
        "positive",
        "wrong_address",
        "wrong_message",
        "tampered_signature",
        "all_hex_message",
    ];
    let actual_cases: Vec<&str> = vectors.iter().map(|v| v.case.as_str()).collect();
    assert_eq!(actual_cases, expected_cases);

    for vector in &vectors {
        let response = verify(&AuthVerifyRequest {
            address: vector.address.clone(),
            public_key: vector.public_key.clone(),
            message: vector.message.clone(),
            signature: vector.signature.clone(),
        });
        assert_eq!(
            response.valid, vector.valid,
            "case '{}': expected valid={}, got valid={} (reason: {:?})",
            vector.case, vector.valid, response.valid, response.reason
        );
        if !vector.valid {
            assert!(
                response.reason.is_some(),
                "case '{}': an invalid result must carry a reason",
                vector.case
            );
        }
    }
}

/// The positive vector must fail differently (or not at all) once any one
/// field is corrupted -- pins down that `verify` actually checks all four
/// fields together, not just the signature in isolation.
#[test]
fn positive_vector_is_sensitive_to_every_field() {
    let vectors = load_vectors();
    let positive = vectors.iter().find(|v| v.case == "positive").unwrap();
    let baseline = verify(&AuthVerifyRequest {
        address: positive.address.clone(),
        public_key: positive.public_key.clone(),
        message: positive.message.clone(),
        signature: positive.signature.clone(),
    });
    assert!(baseline.valid);

    let mut bad_pubkey = positive.public_key.clone();
    let last = bad_pubkey.pop().unwrap();
    bad_pubkey.push(if last == '0' { '1' } else { '0' });
    let response = verify(&AuthVerifyRequest {
        address: positive.address.clone(),
        public_key: bad_pubkey,
        message: positive.message.clone(),
        signature: positive.signature.clone(),
    });
    assert!(!response.valid);
}

#[test]
fn malformed_hex_fields_are_rejected_not_panicking() {
    let response = verify(&AuthVerifyRequest {
        address: "txch1dhxy800eq57a9y9zlhuw0anfv9ekl586c5zm8cp2tng7tpr8rl5se62cng".to_string(),
        public_key: "not hex".to_string(),
        message: "hello".to_string(),
        signature: "0x00".to_string(),
    });
    assert!(!response.valid);
    assert!(response.reason.unwrap().contains("publicKey"));
}
